import{_ as t,o as a,c as o,a4 as d}from"./chunks/framework.DCsBdTIw.js";const u=JSON.parse('{"title":"Cherry Studio","description":"Add Tokeness as a custom provider in Cherry Studio, configure the API address, API key, and model list.","frontmatter":{"title":"Cherry Studio","description":"Add Tokeness as a custom provider in Cherry Studio, configure the API address, API key, and model list."},"headers":[],"relativePath":"integrations/cherry-studio.md","filePath":"integrations/cherry-studio.md","lastUpdated":1784332800000}'),r={name:"integrations/cherry-studio.md"};function s(i,e,n,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="cherry-studio" tabindex="-1">Cherry Studio <a class="header-anchor" href="#cherry-studio" aria-label="Permalink to &quot;Cherry Studio&quot;">​</a></h1><p>Cherry Studio supports custom AI providers. Tokeness connects through the OpenAI-compatible interface — fill in the API address and API key in a custom provider, then add model names manually.</p><h2 id="connection-details" tabindex="-1">Connection Details <a class="header-anchor" href="#connection-details" aria-label="Permalink to &quot;Connection Details&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Provider Type</td><td><code>OpenAI</code> or a custom OpenAI-compatible provider</td></tr><tr><td>Provider Name</td><td><code>Tokeness</code></td></tr><tr><td>API Address / Base URL</td><td><code>https://n.tokeness.dev/v1</code></td></tr><tr><td>API Key</td><td>A key created in the Tokeness console</td></tr><tr><td>Model ID</td><td>The full model name from the Tokeness model catalog</td></tr></tbody></table><p>Field labels may differ across Cherry Studio versions. As long as the field means API address, API key, or model management, fill it in according to the table above.</p><h2 id="_1-prepare-tokeness" tabindex="-1">1. Prepare Tokeness <a class="header-anchor" href="#_1-prepare-tokeness" aria-label="Permalink to &quot;1. Prepare Tokeness&quot;">​</a></h2><p>Prepare the following first:</p><ol><li>A dedicated API key for Cherry Studio.</li><li>A confirmed, working model name.</li><li>Available balance.</li></ol><p>Name the key something like:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cherry-studio-local</span></span></code></pre></div><p>If you plan to configure multiple assistants or knowledge bases inside Cherry Studio, create separate keys for different use cases.</p><h2 id="_2-create-a-custom-provider" tabindex="-1">2. Create a Custom Provider <a class="header-anchor" href="#_2-create-a-custom-provider" aria-label="Permalink to &quot;2. Create a Custom Provider&quot;">​</a></h2><p>Open Cherry Studio settings and find the model service, Provider, or provider configuration section.</p><p>Create a new provider:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Name: Tokeness</span></span>
<span class="line"><span>Type: OpenAI</span></span>
<span class="line"><span>API Address: https://n.tokeness.dev/v1</span></span>
<span class="line"><span>API Key: your Tokeness API key</span></span></code></pre></div><p>Before saving, if the interface has a Check, Test, or Verify button, click it once. If validation fails, do not continue adding models — check the key and API address first.</p><h2 id="_3-add-models" tabindex="-1">3. Add Models <a class="header-anchor" href="#_3-add-models" aria-label="Permalink to &quot;3. Add Models&quot;">​</a></h2><p>Cherry Studio custom providers usually require models to be added manually.</p><p>Steps:</p><ol><li>Open the Tokeness model catalog.</li><li>Copy the full model name.</li><li>Return to Cherry Studio model management.</li><li>Click Add Model.</li><li>Paste the model name.</li><li>Save.</li></ol><p>Keep the full model name exactly — preserve case, vendor prefix, and version number.</p><h2 id="_4-set-the-default-model" tabindex="-1">4. Set the Default Model <a class="header-anchor" href="#_4-set-the-default-model" aria-label="Permalink to &quot;4. Set the Default Model&quot;">​</a></h2><p>After adding models, select the Tokeness provider and the corresponding model on the Cherry Studio chat page.</p><p>For a first test, send:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Reply with a single sentence confirming the model is now available.</span></span></code></pre></div><p>Then open the Tokeness usage logs and confirm the request reached Tokeness.</p><h2 id="_5-multiple-provider-configurations" tabindex="-1">5. Multiple Provider Configurations <a class="header-anchor" href="#_5-multiple-provider-configurations" aria-label="Permalink to &quot;5. Multiple Provider Configurations&quot;">​</a></h2><p>If you have several use cases, you can create multiple Tokeness providers:</p><table tabindex="0"><thead><tr><th>Provider name</th><th>Use case</th></tr></thead><tbody><tr><td><code>Tokeness Chat</code></td><td>Everyday chat</td></tr><tr><td><code>Tokeness Coding</code></td><td>Code-related conversations</td></tr><tr><td><code>Tokeness Low Cost</code></td><td>Summaries, translations, simple Q&amp;A</td></tr><tr><td><code>Tokeness Test</code></td><td>Small-quota testing</td></tr></tbody></table><p>These providers can share the same Base URL — only the key and model configuration need to differ.</p><h2 id="_6-troubleshooting" tabindex="-1">6. Troubleshooting <a class="header-anchor" href="#_6-troubleshooting" aria-label="Permalink to &quot;6. Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Action</th></tr></thead><tbody><tr><td>Check fails</td><td>Verify the API address, key, and balance</td></tr><tr><td>401 Unauthorized</td><td>Re-copy the API key</td></tr><tr><td>404 Not Found</td><td>Set the API address to <code>https://n.tokeness.dev/v1</code></td></tr><tr><td>Model list is empty</td><td>Add model names manually</td></tr><tr><td>model not found</td><td>Re-copy the model name from the model catalog</td></tr><tr><td>No Tokeness logs</td><td>The current session is not using the Tokeness provider</td></tr><tr><td>Usage cannot be distinguished</td><td>Create a separate key for Cherry Studio</td></tr></tbody></table><h2 id="external-documentation" tabindex="-1">External Documentation <a class="header-anchor" href="#external-documentation" aria-label="Permalink to &quot;External Documentation&quot;">​</a></h2><ul><li><a href="https://docs.cherry-ai.com/docs/en-us/pre-basic/providers/zi-ding-yi-fu-wu-shang" target="_blank" rel="noreferrer">Cherry Studio Custom Provider</a></li><li><a href="https://docs.cherry-ai.com/docs/en-us/pre-basic/providers/newapi" target="_blank" rel="noreferrer">Cherry Studio NewAPI Provider Example</a></li></ul>`,34)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
